func displayHours(hours []WeeklyHour) []string {
	sorted := make([]WeeklyHour, len(hours))
	copy(sorted, hours)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Weekday != sorted[j].Weekday {
			return sorted[i].Weekday < sorted[j].Weekday
		}
		return minutes(sorted[i].Start) < minutes(sorted[j].Start)
	})
	labels := make([]string, 0, len(sorted))
	for _, h := range sorted {
		if minutes(h.End) < minutes(h.Start) {
			labels = append(labels, fmt.Sprintf("%s %s – 次日 %s", weekdayName(h.Weekday), h.Start, h.End))
		} else {
			labels = append(labels, fmt.Sprintf("%s %s – %s", weekdayName(h.Weekday), h.Start, h.End))
		}
	}
	return labels
}

func weekdayName(weekday int) string {
	return [...]string{"", "周一", "周二", "周三", "周四", "周五", "周六", "周日"}[weekday]
}

// newID 生成非空、概率上唯一的记录标识。
func newID() string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		// crypto/rand 失败极不寻常；退化为纳秒时间戳，仍保证非空且基本唯一。
		return fmt.Sprintf("v-%d", time.Now().UnixNano())
	}
	return hex.EncodeToString(b)
}

