		{"weeklyHours wrong type", func(p map[string]any) { p["weeklyHours"] = "none" }},
		{"hour item wrong type", func(p map[string]any) { p["weeklyHours"] = []any{"x"} }},
		{"weekday out of range", func(p map[string]any) {
