		{"bad timezone", `{"name":"x","capacity":10,"timezone":"Mars/Olympus","weeklyHours":[]}`},
		{"bad time", `{"name":"x","capacity":10,"timezone":"UTC","weeklyHours":[{"weekday":1,"start":"25:00","end":"26:00"}]}`},
