		{"equal times", `{"name":"x","capacity":10,"timezone":"UTC","weeklyHours":[{"weekday":1,"start":"10:00","end":"10:00"}]}`},
		{"trailing value", `{"name":"x","capacity":10,"timezone":"UTC","weeklyHours":[]}{}`},
