	defer s.mu.Unlock()

	venues, err := s.load()
	if err != nil {
		return Venue{}, err
	}

	venue, err := buildVenue(payload)
	if err != nil {
		return Venue{}, err
	}

	venue.ID = newID()
	for _, existing := range venues {
		if existing.ID == venue.ID {
			// 极小概率的随机碰撞：重新生成一次。
			venue.ID = newID()
			break
		}
	}
