283	func hourField(obj map[string]any, i int, field string) (string, error) {
284		value, ok := obj[field]
285		if !ok || value == nil {
286			return "", badRequest("weeklyHours[%d].%s 类型错误：应为 HH:mm 时间", i, field)
287		}
288		str, ok := value.(string)
289		if !ok || !validHHMM(str) {
290			return "", badRequest("weeklyHours[%d].%s 时间无效，必须为 00:00 至 23:59 的 HH:mm 格式", i, field)
291		}
292		return str, nil
293	}
294	
295	// validHHMM 严格校验 HH:mm：两位小时、冒号、两位分钟，范围 00:00–23:59。
296	func validHHMM(value string) bool {
297		if len(value) != 5 || value[2] != ':' {
298			return false
299		}
300		for i, c := range value {
301			if i == 2 {
302				continue
303			}
304			if c < '0' || c > '9' {
305				return false
306			}
307		}
308		hour := int(value[0]-'0')*10 + int(value[1]-'0')
309		minute := int(value[3]-'0')*10 + int(value[4]-'0')
310		return hour <= 23 && minute <= 59
311	}
312	
313	func minutes(value string) int {
314		return int(value[0]-'0')*600 + int(value[1]-'0')*60 +
315			int(value[3]-'0')*10 + int(value[4]-'0')
316	}
317	
318	// interval 是展开到周时间轴上的一段开放时间，单位为分钟。
319	// 周一 00:00 为起点 0。
320	type interval struct {
321		start int
322		end   int
323		label string
324	}
325	
326	// validateHours 检查所有时段是否相交或互相包含。
327	// 时段按“开始星期 × 开始时间”展开；跨午夜时段延伸到次日。
328	// 为检查周日延续到周一的情况，所有时段再复制一份到下一周坐标系。
329	// 前一段结束与下一段开始相同时允许保存。
330	func validateHours(hours []WeeklyHour) error {
331		intervals := make([]interval, 0, len(hours)*2)
332		for _, h := range hours {
333			startMin := minutes(h.Start)
334			endMin := minutes(h.End)
335			label := fmt.Sprintf("%s %s-%s", weekdayName(h.Weekday), h.Start, h.End)
336			if startMin == endMin {
337				return badRequest("开放时段无效：%s 的结束时间与开始时间相同", label)
338			}
339			start := (h.Weekday-1)*1440 + startMin
340			end := (h.Weekday-1)*1440 + endMin
341			if endMin < startMin {
342				end += 1440 // 跨午夜，次日结束
343			}
344			intervals = append(intervals, interval{start: start, end: end, label: label})
345		}
346		// 复制到下一周，用于检测周日跨午夜与下周一时段相交。
347		base := make([]interval, len(intervals))
348		copy(base, intervals)
349		for _, iv := range base {
350			intervals = append(intervals, interval{
351				start: iv.start + 7*1440,
352				end:   iv.end + 7*1440,
353				label: iv.label,
354			})
355		}
356		sort.Slice(intervals, func(i, j int) bool {
357			if intervals[i].start != intervals[j].start {
358				return intervals[i].start < intervals[j].start
359			}
360			return intervals[i].end < intervals[j].end
361		})
362		for i := 1; i < len(intervals); i++ {
363			if intervals[i].start < intervals[i-1].end {
364				return badRequest("开放时段存在相交：%s 与其他时段重叠", intervals[i].label)
365			}
366		}
367		return nil
368	}
369	
370	func weekdayName(weekday int) string {
371		return [...]string{"", "周一", "周二", "周三", "周四", "周五", "周六", "周日"}[weekday]
372	}
373	
374	// newID 生成非空、概率上唯一的记录标识。
375	func newID() string {
376		b := make([]byte, 16)
377		if _, err := rand.Read(b); err != nil {
378			// crypto/rand 失败极不寻常；退化为纳秒时间戳，仍保证非空且基本唯一。
379			return fmt.Sprintf("v-%d", time.Now().UnixNano())
380		}
381		return hex.EncodeToString(b)
382	}
383	
384	func idTaken(venues []Venue, id string) bool {
385		for _, v := range venues {
386			if v.ID == id {
387				return true
388			}
389		}
390		return false
391	}
